-- Living Population module install script.
-- Idempotent: it runs on every enable, so it only creates the table when absent and never drops data.
-- Columns added after a table was first created are added on startup by the module itself (ColdBotDao.ensureColumns).
-- The table is module-owned and namespaced; stock code never reads or writes it.
CREATE TABLE IF NOT EXISTS living_population_bots (
	id BIGINT NOT NULL AUTO_INCREMENT,
	name VARCHAR(35) NOT NULL,
	race VARCHAR(16) NOT NULL,
	class_id INT NOT NULL DEFAULT 0,
	level INT NOT NULL DEFAULT 1,
	level_exp BIGINT NOT NULL DEFAULT 0,
	sp BIGINT NOT NULL DEFAULT 0,
	adena BIGINT NOT NULL DEFAULT 0,
	region VARCHAR(64) DEFAULT NULL,
	x INT NOT NULL DEFAULT 0,
	y INT NOT NULL DEFAULT 0,
	z INT NOT NULL DEFAULT 0,
	activity VARCHAR(24) NOT NULL DEFAULT 'hunting',
	phase VARCHAR(8) NOT NULL DEFAULT 'cold',
	created_at BIGINT NOT NULL DEFAULT 0,
	updated_at BIGINT NOT NULL DEFAULT 0,
	last_resolved_at BIGINT NOT NULL DEFAULT 0,
	next_resolve_at BIGINT NOT NULL DEFAULT 0,
	hot_lock TINYINT(1) NOT NULL DEFAULT 0,
	char_id BIGINT NOT NULL DEFAULT 0,
	soulshots BIGINT NOT NULL DEFAULT 0,
	potions BIGINT NOT NULL DEFAULT 0,
	gear_tier INT NOT NULL DEFAULT 0,
	goal VARCHAR(16) NOT NULL DEFAULT 'hunting',
	reward_claimed TINYINT(1) NOT NULL DEFAULT 0,
	stats_json TEXT DEFAULT NULL,
	zone VARCHAR(64) DEFAULT NULL,
	town VARCHAR(64) DEFAULT NULL,
	escapes BIGINT NOT NULL DEFAULT 0,
	leg VARCHAR(200) DEFAULT NULL,
	loot BIGINT NOT NULL DEFAULT 0,
	deaths INT NOT NULL DEFAULT 0,
	risk VARCHAR(255) DEFAULT NULL,
	quest VARCHAR(64) DEFAULT NULL,
	skills TEXT DEFAULT NULL,
	gear VARCHAR(255) DEFAULT NULL,
	PRIMARY KEY (id),
	UNIQUE KEY uk_living_population_name (name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
